presetParts.presetInit:
n = 0;
loop (100000,megabuf(n)=0;gmegabuf(n)=0;n += 1;);

posx = rand(10); posy = rand(10);
ranx = rand (1); rany = rand(1);
ranh = rand(10);
t0 = time;
st = 0.5; st_=0.5; sp = 1;

presetParts.perFrame:
dec_med = 1-0.02*30/fps; dec_s = 1-0.005*30/fps; 
vol = (bass_att+med_att+treb_att)/3; vol_ = vol_*dec_s + (1-dec_s)*vol;

is_beat = above(vol, 18*peak) * above (time, t0+2.5);
t0a  = if(is_beat,t0,t0a); t0 = if(is_beat,time,t0);
peak = if(is_beat,vol,peak*dec_med);
index = (index + is_beat) %8;


//dir
dir = 0.7*sin(time*.0162+rany*6);
q2 = dir+0.5; 
q3 = sin(dir);
q4 = cos(dir);

//scaling plane
q7 = 0.002;

//movement
if (is_beat, mdir = if (bnot (mdir ==0), 0, int (rand(3))-1),0); 
mdir_ = mdir_*0.96 + 0.04*abs(mdir)*3.14/2;

sp = 0.007;
dpx =  sin(mdir_) *sp*1.5;
dpy =  -cos(mdir_) * sp;
posx += dpx/fps;
posy += dpy/fps;
q10 = posx; q11 = posy;
q12 = dpx/fps ; q13 = dpy/fps;

//start ran for warp mod 
q15 = ranx;
q16 = rany;

test = (t0-time)*0.047-3.14/2;
view = 0.7 + min(1, max (-1, 2*sin(test)))*0.17;

//Alti
q8 = 4 + 3* sin(test) + (st_*2+view-0.55)*16;
q8 = 1;
//hory (Kippung)
q6 = view * (1-st_) + st_*2;

q6  = 0.7;

q17 = 0.4 + 0.2 *sin(time*0.042); q18 = 0.4;
monitor = q15;

