static const float2 hor = texsize.zw*float2 (1.5,0), dir = float2 (q3,q4), modran = float2 (q15,q16);
static const float2 dpxy = float2 (q12, q13);
static const float3 mov = float3 (q10,q11,0);

float2 noise2 (float2 uvi) {float2 tmp = 1; float s = 1;
  for (int n = 1; n <= 2; n +=1 ) {tmp *= 1-tex2D(snl,uvi*s); s*= 3;} return tmp;}

float2 noise3 (float3 uvi, float3 mod) {uvi *= 0.16; float tmp = 1; float s = 2; float diff = 0;
  tmp = tex2D(sampler_noise_mq,uvi).r*2-2; 
//  for (int n = 2; n <= 5; n +=1 ) {tmp *= (1-tex2D(snl,uvi.xy*s)*(0.8+mod.y/2)/s); s*= 3;}
  for (int n = 2; n <= 5; n +=1 ) {tmp += tex2D(snl,uvi.xy*s)/s; s*= 3;}
  tmp = lerp (q17,tmp,saturate(uvi.z/6));
  return 1-pow (tmp,0.8+mod.x);}

float3 rs_lav (float2 uvi, float berg) {  float z; float2 rs;
  z = 1/(uvi.y+hory)*(alti-berg*16); //z = clamp(z,0,4/xyscale);
  z = 1/(uvi.y+hory)*(alti-berg*z*q18); //z = clamp(z,0,4/xyscale);
  rs.x = uvi.x * 1.25*aspect.x/aspect.y*z ; rs.y = z; 
