float zo = 1.0/rsl.z;
i=0, p=0;
for (int n=1; n <= quality; n++) {
  p =  ((lav_gnd+noise3 (rsl, mod))/quality);
  i += p;  lav_gnd -= p*0.2+i*0.1; rsl = rs_lav(uv1,lav_gnd)+mov;}

l = saturate(-lav_gnd);
d= 1.75;
dz = -1.5/rsl.z*xyscale*d*dir;

rsl3 = rsl * 8;
ripple = ((noise2 (rsl3-dz) - noise2 (rsl3+dz))* (1-l))*16/rsl.z+0.04;
ripple += (noise3 (rsl-float3 (dz,0),mod) - noise3 (rsl+float3 (dz,0),mod))*(1-l)/d/sqrt(50+rsl.z)*1600;
ripple = 1-exp(-ripple);

