float2 noise2 (float2 uvi, float h) {float2 tmp = 0; float s = 1;
  for (int n = 1; n <= 3; n +=1 ) {tmp += tex2D(sampler_noise_mq,(uvi)*s+time*0.003)/s; s*= 3+h*-0.0;}
  return sat (abs(tmp*-1)-0.2);}

float3 rs_lav (float2 uvi, float berg) {  float z; float2 rs;
  z = 1/(uvi.y+hory)*(alti-berg*16); 
  z = 1/(uvi.y+hory)*(alti-berg*z*q18); 
  rs.x = uvi.x * 1.25*aspect.x/aspect.y*z ; rs.y = z; 
  return float3(rs*xyscale,z)+mov*1; }


